INSERT INTO `problem` VALUES (62,'删除链表的倒数第 N 个结点','给你一个链表，删除链表的倒数第 `n`* *个结点，并且返回链表的头结点。','head: 链表节点数组（如 [2,4,3] 表示 2→4→3）\nn: 整数','链表节点数组（如 [2,4,3] 表示 2→4→3）','[\"head = [1,2,3,4,5], n = 2\", \"head = [1], n = 1\", \"head = [1,2], n = 1\"]','[\"[1,2,3,5]\", \"[]\", \"[1]\"]','中等',2048,2048,'链表中结点的数目为 sz 1 <= sz <= 30 0 <= Node.val <= 100 1 <= n <= sz\n\n进阶：你能尝试使用一趟扫描实现吗？',1,14,'9 14 23 92 49 78 90 59 94 81 76 71 38 37 6 70 68 2 0 9 99\n12\n---\n69 31 52 78 59 99 97 57 59 82 55 19 63 20 50 80 83 14 85 29 3 80 25 18\n3\n---\n9 81 47 30 28 92 99 69 18 17 94 13 36 23 58 22 55 97 3 24 85 36\n13\n---\n79 45 4 70 89 57 10 32 34 86 86 20 94 63 46 41 79 13 76 41 91 38 97 93 59 72 13 30 71 18\n15\n---\n43 51 52 21 57 44 40 83 63 70 95 25 16 76 51 25 38\n5\n---\n16 57 65 99 24 25 75 24 14 17 12 64 16 52 74 33 51 57 84 52 85 40 53 43 44 27 33 50 81 52\n7','9 14 23 92 49 78 90 59 94 76 71 38 37 6 70 68 2 0 9 99\n---\n69 31 52 78 59 99 97 57 59 82 55 19 63 20 50 80 83 14 85 29 3 25 18\n---\n9 81 47 30 28 92 99 69 18 94 13 36 23 58 22 55 97 3 24 85 36\n---\n79 45 4 70 89 57 10 32 34 86 86 20 94 63 46 79 13 76 41 91 38 97 93 59 72 13 30 71 18\n---\n43 51 52 21 57 44 40 83 63 70 95 25 76 51 25 38\n---\n16 57 65 99 24 25 75 24 14 17 12 64 16 52 74 33 51 57 84 52 85 40 53 44 27 33 50 81 52','official','LeetCode','https://leetcode.cn/problems/remove-nth-node-from-end-of-list/description/','','sz 1 30\nhead int[sz] 0 100\nn 1 sz\nrounds 6',' #include <iostream>\n  #include <vector>\n  #include <sstream>\n  using namespace std;\n\n  struct ListNode {\n      int val;\n      ListNode *next;\n      ListNode() : val(0), next(nullptr) {}\n      ListNode(int x) : val(x), next(nullptr) {}\n      ListNode(int x, ListNode *next) : val(x), next(next) {}\n  };\n\n  class Solution {\n  public:\n      ListNode* removeNthFromEnd(ListNode* head, int n) {\n          ListNode* dummy = new ListNode(0, head);\n          ListNode* slow = dummy;\n          ListNode* fast = dummy;\n\n          for (int i = 0; i < n; ++i) {\n              fast = fast->next;\n          }\n\n          while (fast->next != nullptr) {\n              slow = slow->next;\n              fast = fast->next;\n          }\n\n          ListNode* toDelete = slow->next;\n          slow->next = slow->next->next;\n          delete toDelete;\n\n          ListNode* newHead = dummy->next;\n          delete dummy;\n          return newHead;\n      }\n  };\n\n  ListNode* createList(const vector<int>& vals) {\n      if (vals.empty()) return nullptr;\n      ListNode* head = new ListNode(vals[0]);\n      ListNode* cur = head;\n      for (size_t i = 1; i < vals.size(); ++i) {\n          cur->next = new ListNode(vals[i]);\n          cur = cur->next;\n      }\n      return head;\n  }\n\n  void printList(ListNode* head) {\n      if (head == nullptr) {\n          cout << endl;\n          return;\n      }\n      while (head != nullptr) {\n          cout << head->val;\n          if (head->next != nullptr) {\n              cout << \" \";\n          }\n          head = head->next;\n      }\n      cout << endl;\n  }\n\n  int main() {\n      vector<int> nums;\n      string line;\n      getline(cin, line);\n      istringstream iss(line);\n      int num;\n      while (iss >> num) {\n          nums.push_back(num);\n      }\n\n      int n;\n      cin >> n;\n\n      if (nums.empty() || n <= 0) return 0;\n\n      ListNode* head = createList(nums);\n      Solution solution;\n      ListNode* result = solution.removeNthFromEnd(head, n);\n      printList(result);\n\n      return 0;\n  }','cpp'),(63,'盛最多水的容器','给定一个长度为 `n` 的整数数组 `height` 。有 `n` 条垂线，第 `i` 条线的两个端点是 `(i, 0)` 和 `(i, height[i])` 。\n\n找出其中的两条线，使得它们与 `x` 轴共同构成的容器可以容纳最多的水。\n\n返回容器可以储存的最大水量。\n\n**说明：**你不能倾斜容器。','height: 整数数组（空格分隔）','整数','[\"[1,8,6,2,5,4,8,3,7]\", \"height = [1,1]\"]','[\"49\", \"1\"]','中等',2048,2048,'n == height.length 2 <= n <= 10 5 0 <= height[i] <= 10 4',1,8,'182 649 350 635 563 887 681 789 889 949 336 871 461 863 366 888 293 760 509 967 579 106 647 457 382 56 913 839 724 414 843 257 542 183 130 477 516 791 466 617 633 858 97 761 387 431 287 442 504 679 992 578 766 994 171 294 775 352 396 552 324 14 399 450 694 577 794 304 152 961 121 909 541 260 352 487 950 405 459 234 665 423 59 238 207 996 18 212 303 359 510 454 551 919 982 212 361 439 897 145 731 747 862 399 968 77 18 222 445 365 179 234 19 65 960 314 417 293 515 377 931 237 69 34 918 619 618 176 521 639 525 712 508 429 133 489 411 985 632 114 787 399 986 765 607 608 34 428 382 844 155 142 991 648 148 565 29 294 498 547 600 383 80 147 466 206 203 622 967 85 201 44 271 475 274 270 329 937 694 426 969 848 575 288 837 631 923 82 842 836 329 563 587 976 946 151 439 902 92 307 943 479 840 738 811 375 447 504 477 577 262 636 24 613 630 484 706 93 571 522 636 680 584 735 851 624 6 480 53 129 906 931 996 396 139 803 353 456 154 146 751 820 789 503 596 826 37 241 312 990 593 538 90 513 714 84 722 420 20 477 957 554 708 463 553 721 990 681 352 345 117 413 746 925 274 605 355 289 646 961 378 803 369 503 610 523 924 218 814 258 575 778 260 294 681 52 68 35 786 65 970 328 243 595 155 24 588 90 823 663 986 696 925 435 114 154 47 605 811 193 613 412 165 71 43 963 745 781 57 600 431 845 579 799 93 532 341 915 610 692 966 885 298 215 650 188 580 370 549 336 172 354 112 868 214 189 985 305 573 888 891 165 585 740 222 197 605 146 42 548 937 813 83 967 280 514 104 878 553 242 641 612 433 816 656 587 598 868 327 224 709 524 192 778 874 744 737 632 999 81 406 55 973 922 613 353 326 255 525 59 821 858 390 193 717 48 8 660 240 238 730 15 870 471 503 685 588 325 596 840 884 378 105 496 736 626 478 428 564 601 853 956 311 237 103 124 860 322 312 649 767 25 223 215 299 438 274 994 102 141 62 606 498 46 917 127 961 72 566 348 200 915 26 200 539 443 437 283 528 411 286 694 919 655 676 244 454 799 958 352 472 688 332 666 930 846 353 322 920 220 799 781 744 194 448 47 340 776 241 508 814 349 929 497 475 422 577 884 829 995 619 62 176 433 334 27 575 932 366 432 533 571 587 519 283 232 645 314 