666 936 629 88 51 798 157 570 422 134 899 641 370 378 972 655 671 722 551 723 576 415 641 40 378 347 117 128 86 116 278 820 677 494 729 1 86 965 369 486 303 216 138 282 970 789 542 200 245 524 808 75 846 514 434 896 991 847 985 144 288 406 117 35 742 730 356 908 385 68 137 772 699 386 391 427 311 512 124 165 881 189 858 935 726 817 334 177 279 384 542 313 321 653 828 416 979 196 831 719 690 466 325 65 574 791 838 885 268 556 533 190 160 722 743 860 321 298 482 508 440 510 437 297 712 492 368 518 324 831 121 679 348 589 530 453 86 288 182 705 566 584 335 863 755','1489180\n---\n5589920\n---\n5278710\n---\n4447533\n---\n4983660\n---\n4260720\n---\n2903584\n---\n3035676\n---\n7942176\n---\n3614177','official','LeetCode','https://leetcode.cn/problems/container-with-most-water/description/','','n 2 10000\nheight int[n] 0 1000\nrounds 10','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int maxArea(vector<int>& height) {\n        int left = 0;\n        int right = height.size() - 1;\n        int maxWater = 0;\n        \n        while (left < right) {\n            int h = min(height[left], height[right]);\n            int w = right - left;\n            maxWater = max(maxWater, h * w);\n            \n            if (height[left] < height[right]) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n        \n        return maxWater;\n    }\n};\n\nint main() {\n    vector<int> height;\n    int num;\n    while (cin >> num) {\n        height.push_back(num);\n    }\n    \n    Solution solution;\n    cout << solution.maxArea(height) << endl;\n    \n    return 0;\n}','cpp');
