< endl;\r\n    return 0;\r\n}',10,'Accepted','全部测试用例通过',0.02,3696,'2026-07-05 16:56:45'),(150,5,21,'test','两数之和','cpp','// template\r\n#include <iostream>\r\n#include <vector>\r\n\r\nusing namespace std;\r\n\r\nint main() {\r\n    int a, b, n;\r\n    cin >> a >> b;\r\n    n = a + b;\r\n    cout << n << endl;\r\n    return 0;\r\n}',11,'Wrong Answer','Case 1: Wrong Answer\n输入:\n[\n  {\n    \"input\": \"4 9\\n2 7 11 15\",\n    \"output\": \"0 1\"\n  },\n  {\n    \"input\": \"3 6\\n3 2 4\",\n    \"output\": \"1 2\"\n  },\n  {\n    \"input\": \"2 3\\n3 3\",\n    \"output\": \"0 1\"\n  },\n  {\n    \"input\": \"5 10\\n1 2 3 4 5\",\n    \"output\": \"3 4\"\n  },\n  {\n    \"input\": \"4 0\\n-1 0 1 2\",\n    \"output\": \"0 2\"\n  }\n]\n实际输出:\n0\n期望输出:\n#include <iostream>\n#include <unordered_map>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, target;\n    cin >> n >> target;\n    \n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    \n    unordered_map<int, int> map;\n    for (int i = 0; i < n; i++) {\n        int complement = target - nums[i];\n        if (map.find(complement) != map.end()) {\n            cout << map[complement] << \" \" << i << endl;\n            return 0;\n        }\n        map[nums[i]] = i;\n    }\n    \n    return 0;\n}',0.01,3716,'2026-07-05 16:59:44'),(151,5,22,'test','两数之和（2）','cpp','// template\r\n#include <iostream>\r\n#include <vector>\r\n\r\nusing namespace std;\r\n\r\nint main() {\r\n    int a, b, n;\r\n    cin >> a >> b;\r\n    n = a + b;\r\n    cout << n << endl;\r\n    return 0;\r\n}',10,'Accepted','全部测试用例通过',0.04,3768,'2026-07-05 17:08:50'),(152,5,22,'test','两数之和（2）','cpp','// template\r\n#include <iostream>\r\n#include <vector>\r\n\r\nusing namespace std;\r\n\r\nint main() {\r\n    int a, b, n;\r\n    cin >> a >> b;\r\n    n = a + b;\r\n    cout << n << endl;\r\n    return 0;\r\n}',10,'Accepted','全部测试用例通过',0.02,3596,'2026-07-05 17:31:12'),(153,5,22,'test','两数之和（2）','cpp','// template\r\n#include <iostream>\r\n#include <vector>\r\n\r\nusing namespace std;\r\n\r\nint main() {\r\n    int a, b, n;\r\n    cin >> a >> b;\r\n    n = a + b;\r\n    cout << n << endl;\r\n    return 0;\r\n}',1,'Compile Error','Case 1: Compile Error\n输入:\n1 2\n判题容器创建失败: Not Found',0,NULL,'2026-07-10 22:39:09'),(154,5,32,'test','两数相加','cpp',' #include <iostream>\n  #include <string>\n  #include <vector>\n  using namespace std;\n\n  struct ListNode {\n      int val;\n      ListNode *next;\n      ListNode(int x) : val(x), next(nullptr) {}\n  };\n\n  // ========== 核心解法（出题人只需改这里）==========\n  ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n      ListNode* pre = new ListNode(0);\n      ListNode* cur = pre;\n      int carry = 0;\n      while (l1 || l2) {\n          int x = l1 ? l1->val : 0;\n          int y = l2 ? l2->val : 0;\n          int sum = x + y + carry;\n          carry = sum / 10;\n          sum = sum % 10;\n          cur->next = new ListNode(sum);\n          cur = cur->next;\n          if (l1) l1 = l1->next;\n          if (l2) l2 = l2->next;\n      }\n      if (carry) cur->next = new ListNode(carry);\n      return pre->next;\n  }\n  // ================================================\n\n  ListNode* parseList(const string& s) {\n      ListNode dummy(0);\n      ListNode* tail = &dummy;\n      string num;\n      for (char c : s) {\n          if (isdigit(c)) {\n              num += c;\n          } else if (!num.empty()) {\n              tail->next = new ListNode(stoi(num));\n              tail = tail->next;\n              num.clear();\n          }\n      }\n      return dummy.next;\n  }\n\n  void printList(ListNode* head) {\n      cout << \"[\";\n      while (head) {\n          cout << head->val;\n          if (head->next) cout << \",\";\n          head = head->next;\n      }\n      cout << \"]\" << endl;\n  }\n\n  int main() {\n      string line1, line2;\n      getline(cin, line1);\n      getline(cin, line2);\n\n      ListNode* l1 = parseList(line1);\n      ListNode* l2 = parseList(line2);\n\n      ListNode* result = addTwoNumbers(l1, l2);\n      printList(result);\n      return 0;\n  }',1,'System Error','判题系统内部错误: -1',0,NULL,'2026-07-12 10:12:49'),(155,5,32,'test','两数相加','cpp',' #include <iostream>\n  #include <string>\n  #include <vector>\n  using namespace std;\n\n  struct ListNode {\n      int val;\n      ListNode *next;\n      ListNode(int x) : val(x), next(nullptr) {}\n  };\n\n  // ========== 核心解法（出题人只需改这里）==========\n  ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n      ListNode* pre = new ListNode(0);\n      ListNode* cur = pre;\n      int carry = 0;\n      while (l1 || l2) {\n          int x = l1 ? l1->val : 0;\n          int y = l2 ? l2->val : 0;\n          int sum = x + y + carry;\n          carry = sum / 10;\n          sum = sum % 10;\n          cur->next = new ListNode(sum);\n          cur = cur->next;\n          if (l1) l1 = l1->next;\n          if (l2) l2 = l2->next;\n      }\n      if (carry) cur->next = new ListNode(carry);\n      return pre->next;\n  }\n  // ================================================\n\n  ListNode* parseList(const string& s) {\n      ListNode dummy(0);\n      ListNode* tail = &dummy;\n      string num;\n      for (char c : s) {\n          if (isdigit(c)) {\n              num += c;\n          } else if (!num.empty()) {\n              tail->next = new ListNode(stoi(num));\n              tail = tail->next;\n              num.clear();\n          }\n      }\n      return dummy.next;\n  }\n\n  void printList(ListNode* head) {\n      cout << \"[\";\n      while (head) {\n          cout << head->val;\n          if (head->next) cout << \",\";\n          head = head->next;\n      }\n      cout << \"]\" << endl;\n  }\n\n  int main() {\n      string line1, line2;\n      getline(cin, line1);\n      getline(cin, line2);\n\n      ListNode* l1 = parseList(line1);\n      ListNode* l2 = parseList(line2);\n\n      ListNode* result = addTwoNumbers(l1, l2);\n      printList(result);\n