hm>\n#include <climits>\nusing namespace std;\n\n// ==================== 你的代码 ====================\nclass Solution {\npublic:\n    string longestPalindrome(string s) {\n        int n = s.size();\n        if (n < 2) {\n            return s;\n        }\n\n        int maxLen = 1;\n        int begin = 0;\n        // dp[i][j] 表示 s[i..j] 是否是回文串\n        vector<vector<int>> dp(n, vector<int>(n));\n        // 初始化：所有长度为 1 的子串都是回文串\n        for (int i = 0; i < n; i++) {\n            dp[i][i] = true;\n        }\n        // 递推开始\n        // 先枚举子串长度\n        for (int L = 2; L <= n; L++) {\n            // 枚举左边界，左边界的上限设置可以宽松一些\n            for (int i = 0; i < n; i++) {\n                // 由 L 和 i 可以确定右边界，即 j - i + 1 = L 得\n                int j = L + i - 1;\n                // 如果右边界越界，就可以退出当前循环\n                if (j >= n) {\n                    break;\n                }\n\n                if (s[i] != s[j]) {\n                    dp[i][j] = false;\n                } else {\n                    if (j - i < 3) {\n                        dp[i][j] = true;\n                    } else {\n                        dp[i][j] = dp[i + 1][j - 1];\n                    }\n                }\n\n                // 只要 dp[i][L] == true 成立，就表示子串 s[i..L] 是回文，此时记录回文长度和起始位置\n                if (dp[i][j] && j - i + 1 > maxLen) {\n                    maxLen = j - i + 1;\n                    begin = i;\n                }\n            }\n        }\n        return s.substr(begin, maxLen);\n    }\n};\n\n// ==================================================\n\nint main() {\n    string line;\n    getline(cin, line);\n    string s = line;\n\n    string result = Solution().longestPalindrome(s);\n    cout << result << endl;\n\n    return 0;\n}\n',10,'Accepted','全部 20 轮多策略测试通过\n\n[复杂度分析] 时间复杂度: O(n²), 空间复杂度: O(n)（含递归栈 O(n)）',0.02,3824,'2026-07-13 00:39:16'),(181,5,37,'test','两数相加','cpp','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <climits>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode *next;\n    ListNode() : val(0), next(nullptr) {}\n    ListNode(int x) : val(x), next(nullptr) {}\n    ListNode(int x, ListNode *next) : val(x), next(next) {}\n};\n\nListNode* parseList(const string& s) {\n    ListNode dummy; ListNode* cur = &dummy;\n    string num;\n    for (char c : s) {\n        if (isdigit(c) || c == \'-\') num += c;\n        else if (!num.empty()) {\n            cur->next = new ListNode(stoi(num));\n            cur = cur->next; num.clear();\n        }\n    }\n    return dummy.next;\n}\nvoid printList(ListNode* head) {\n    cout << \"[\";\n    while (head) { cout << head->val; if (head->next) cout << \",\"; head = head->next; }\n    cout << \"]\" << endl;\n}\n// ==================== 你的代码 ====================\nclass Solution {\npublic:\n    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n        ListNode *head = nullptr, *tail = nullptr;\n        int carry = 0;\n        while (l1 || l2) {\n            int n1 = l1 ? l1->val: 0;\n            int n2 = l2 ? l2->val: 0;\n            int sum = n1 + n2 + carry;\n            if (!head) {\n                head = tail = new ListNode(sum % 10);\n            } else {\n                tail->next = new ListNode(sum % 10);\n                tail = tail->next;\n            }\n            carry = sum / 10;\n            if (l1) {\n                l1 = l1->next;\n            }\n            if (l2) {\n                l2 = l2->next;\n            }\n        }\n        if (carry > 0) {\n            tail->next = new ListNode(carry);\n        }\n        return head;\n    }\n};\n\n// ==================================================\n\nint main() {\n    string line;\n    getline(cin, line);\n    ListNode* l1 = parseList(line);\n    getline(cin, line);\n    ListNode* l2 = parseList(line);\n\n    ListNode* result = Solution().addTwoNumbers(l1, l2);\n    printList(result);\n\n    return 0;\n}\n',10,'Accepted','全部 20 轮多策略测试通过\n\n[复杂度分析] 时间复杂度: O(n), 空间复杂度: O(1)',0.36,16308,'2026-07-14 14:25:52'),(182,5,41,'test','最长回文子串','cpp','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <climits>\nusing namespace std;\n\n// ==================== 你的代码 ====================\nclass Solution {\npublic:\n    string longestPalindrome(string s) {\n        int n = s.size();\n        if (n < 2) {\n            return s;\n        }\n\n        int maxLen = 1;\n        int begin = 0;\n        // dp[i][j] 表示 s[i..j] 是否是回文串\n        vector<vector<int>> dp(n, vector<int>(n));\n        // 初始化：所有长度为 1 的子串都是回文串\n        for (int i = 0; i < n; i++) {\n            dp[i][i] = true;\n        }\n        // 递推开始\n        // 先枚举子串长度\n        for (int L = 2; L <= n; L++) {\n            // 枚举左边界，左边界的上限设置可以宽松一些\n            for (int i = 0; i < n; i++) {\n                // 由 L 和 i 可以确定右边界，即 j - i + 1 = L 得\n                int j = L + i - 1;\n                // 如果右边界越界，就可以退出当前循环\n                if (j >= n) {\n                    break;\n                }\n\n                if (s[i] != s[j]) {\n                    dp[i][j] = false;\n                } else {\n                    if (j - i < 3) {\n                        dp[i][j] = true;\n                    } else {\n                        dp[i][j] = dp[i + 1][j - 1];\n                    }\n                }\n\n                // 只要 dp[i][L] == true 成立，就表示子串 s[i..L] 是回文，此时记录回文长度和起始位置\n                if (dp[i][j] && j - i + 1 > maxLen) {\n                    maxLen = j - i + 1;\n                    begin = i;\n                }\n            }\n        }\n        return s.substr(begin, maxLen);\n    }\n};\n\n\n// ==================================================\n\nint main() {\n    string line;\n    getline(cin, line);\n    string s = line;\n\n    string result = Solution().longestPalindrome(s);\n    cout << result << endl;\n\n    return 0;\n}\n',10,'Accepted','全部 20 轮多策略测试通过\n\n[复杂度分析] 时间复杂度: O(n²), 空间复杂度: O(n)（含递归栈 O(n)）',0.04,7236,'2026-07-14 22:53:35'),(183,5,41,'test','最长回文子串','cpp','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <climits>\nusing namespace std;\n\n// ==================== 你的代码 ====================\nclass Solution {\npublic:\n    string longestPalindrome(string s) {\n        int n = s.size();\n        if (n < 2) {\n            return s;\n        }\n\n        int maxLen = 1;\n        int begin = 0;\n        // dp[i][j] 表示 s[i..j] 是否是回文串\n        vector<vector<int>> dp(n, vector<int>(n));\n        // 初始化：所有长度为 1 的子串都是回文串\n        for (int i = 0; i < n; i++) {\n            dp[i][i] = true;\n        }\n        // 递推开始\n        // 先枚举子串长度\n        for (int L = 2; L <= n; L++) {\n            // 枚举左边界，左边界的上限设置可以宽松一些\n            for (int i = 0; i < n; i++) {\n                // 由 L 和 i 可以确定右边界，即 j - i + 1 = L 得\n                int j = L + i - 1;\n                // 如果右边界越界，就可以退出当前循环\n                if (j >= n) {\n                    break;\n                }\n\n                if (s[i] != s[j]) {\n                    dp[i][j] = false;\n                } else {\n                    if (j - i < 3) {\n                        dp[i][j] = true;\n                    } else {\n                        dp[i][j] = dp[i + 1][j - 1];\n                    }\n                }\n\n                // 只要 dp[i][L] == true 成立，就表示子串 s[i..L] 是回文，此时记录回文长度和起始位置\n                if (dp[i][j] && j - i + 1 > maxLen) {\n                    maxLen = j - i + 1;\n                    begin = i;\n                }\n            }\n        }\n        return s.substr(begin, maxLen);\n    }\n};\n\n\n// ==================================================\n\nint main() {\n    string line;\n    getline(cin, line);\n    string s = line;\n\n    string result = Solution().longestPalindrome(s);\n    cout << result << endl;\n\n    return 0;\n}\n',10,'Accepted','全部 20 轮多策略测试通过\n\n[复杂度分析] 时间复杂度: O(n²), 空间复杂度: O(n)（含递归栈 O(n)）',0.03,7308,'2026-07-14 23:19:43'),(184,5,41,'test','最长回文子串','cpp','#include <iostream>\n#include <string>\n#include 