>\nusing namespace std;\n\n// ==================== 你的代码 ====================\nclass Solution {\npublic:\n    bool isMatch(string s, string p) {\n        int m = s.size();\n        int n = p.size();\n\n        auto matches = [&](int i, int j) {\n            if (i == 0) {\n                return false;\n            }\n            if (p[j - 1] == \'.\') {\n                return true;\n            }\n            return s[i - 1] == p[j - 1];\n        };\n\n        vector<vector<int>> f(m + 1, vector<int>(n + 1));\n        f[0][0] = true;\n        for (int i = 0; i <= m; ++i) {\n            for (int j = 1; j <= n; ++j) {\n                if (p[j - 1] == \'*\') {\n                    f[i][j] |= f[i][j - 2];\n                    if (matches(i, j - 1)) {\n                        f[i][j] |= f[i - 1][j];\n                    }\n                }\n                else {\n                    if (matches(i, j)) {\n                        f[i][j] |= f[i - 1][j - 1];\n                    }\n                }\n            }\n        }\n        return f[m][n];\n    }\n};\n\n\n// ==================================================\n\nint main() {\n    string line;\n    getline(cin, line);\n    string s = line;\n    getline(cin, line);\n    string p = line;\n\n    void result = Solution().isMatch(s, p);\n\n    return 0;\n}\n',2,'Compile Error','/app/Main.cpp: In function \'int main()\':\n/app/Main.cpp:56:10: error: variable or field \'result\' declared void\n   56 |     void result = Solution().isMatch(s, p);\n      |          ^~~~~~\n',0,NULL,'2026-07-15 22:39:41'),(186,5,42,'test','正则表达式匹配','cpp','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <climits>\nusing namespace std;\n\n// ==================== 你的代码 ====================\nclass Solution {\npublic:\n    bool isMatch(string s, string p) {\n        int m = s.size();\n        int n = p.size();\n\n        auto matches = [&](int i, int j) {\n            if (i == 0) {\n                return 