(isdigit(c) || c == \'-\') num += c;\n        else if (!num.empty()) {\n            cur->next = new ListNode(stoi(num));\n            cur = cur->next; num.clear();\n        }\n    }\n    return dummy.next;\n}\nvoid printList(ListNode* head) {\n    cout << \"[\";\n    while (head) { cout << head->val; if (head->next) cout << \",\"; head = head->next; }\n    cout << \"]\" << endl;\n}\n// ==================== 你的代码 ====================\nclass Solution {\npublic:\n    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n        ListNode *head = nullptr, *tail = nullptr;\n        int carry = 0;\n        while (l1 || l2) {\n            int n1 = l1 ? l1->val: 0;\n            int n2 = l2 ? l2->val: 0;\n            int sum = n1 + n2 + carry;\n            if (!head) {\n                head = tail = new ListNode(sum % 10);\n            } else {\n                tail->next = new ListNode(sum % 10);\n                tail = tail->next;\n            }\n            carry = sum / 10;\n            if (l1) {\n                l1 = l1->next;\n            }\n            if (l2) {\n                l2 = l2->next;\n            }\n        }\n        if (carry > 0) {\n            tail->next = new ListNode(carry);\n        }\n        return head;\n    }\n};\n\n// ==================================================\n\nint main() {\n    string line;\n    getline(cin, line);\n    ListNode* l1 = parseList(line);\n    getline(cin, line);\n    ListNode* l2 = parseList(line);\n\n    ListNode* result = Solution().addTwoNumbers(l1, l2);\n    printList(result);\n\n    return 0;\n}\n',1,'System Error','标程编译失败: /app/Standard.cpp:3:5: error: \'ListNode\' does not name a type\n    3 |     ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n      |     ^~~~~~~~\n',0,NULL,'2026-07-31 12:01:19'),(195,5,44,'test','两数之和','cpp','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <climits>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode *next;\n    ListNode() : val(0), next(nullptr) {}\n    ListNode(int x) : val(x), next(nullptr) {}\n    ListNode(int x, ListNode *next) : val(x), next(next) {}\n};\n\nListNode* parseList(const string& s) {\n    ListNode dummy; ListNode* cur = &dummy;\n    string num;\n    for (char c : s) {\n        if (isdigit(c) || c == \'-\') num += c;\n        else if (!num.empty()) {\n            cur->next = new ListNode(stoi(num));\n            cur = cur->next; num.clear();\n        }\n    }\n    return dummy.next;\n}\nvoid printList(ListNode* head) {\n    cout << \"[\";\n    while (head) { cout << head->val; if (head->next) cout << \",\"; head = head->next; }\n    cout << \"]\" << endl;\n}\n// ==================== 你的代码 ====================\nclass Solution {\npublic:\n    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n        ListNode *head = nullptr, *tail = nullptr;\n        int carry = 0;\n        while (l1 || l2) {\n            int n1 = l1 ? l1->val: 0;\n            int n2 = l2 ? l2->val: 0;\n            int sum = n1 + n2 + carry;\n            if (!head) {\n                head = tail = new ListNode(sum % 10);\n            } else {\n                tail->next = new ListNode(sum % 10);\n                tail = tail->next;\n            }\n            carry = sum / 10;\n            if (l1) {\n                l1 = l1->next;\n            }\n            if (l2) {\n                l2 = l2->next;\n            }\n        }\n        if (carry > 0) {\n            tail->next = new ListNode(carry);\n        }\n        return head;\n    }\n};\n\n// ==================================================\n\nint main() {\n    string line;\n    getline(cin, line);\n    ListNode* l1 = parseList(line);\n    getline(cin, line);\n    ListNode* l2 = parseList(line);\n\n    ListNode* result = Solution().addTwoNumbers(l1, l2);\n    printList(result);\n\n    return 0;\n}\n',11,'Wrong Answer','第 1/1 个测试用例答案错误\n期望输出:\n[0,1]\n\n实际输出:\n[2,7,1,6,1]\n\n[复杂度分析] 时间复杂度: O(n), 空间复杂度: O(1)',0.01,3868,'2026-07-31 12:04:59'),(196,5,44,'test','两数之和','cpp','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <climits>\nusing namespace std;\n\n// ==================== 你的代码 ====================\nclass Solution {\npublic:\n    string longestPalindrome(string s) {\n        int n = s.size();\n        if (n < 2) {\n            return s;\n        }\n\n        int maxLen = 1;\n        int begin = 0;\n        // dp[i][j] 表示 s[i..j] 是否是回文串\n        vector<vector<int>> dp(n, vector<int>(n));\n        // 初始化：所有长度为 1 的子串都是回文串\n        for (int i = 0; i < n; i++) {\n            dp[i][i] = true;\n        }\n        // 递推开始\n        // 先枚举子串长度\n        for (int L = 2; L <= n; L++) {\n            // 枚举左边界，左边界的上限设置可以宽松一些\n            for (int i = 0; i < n; i++) {\n                // 由 L 和 i 可以确定右边界，即 j - i + 1 = L 得\n                int j = L + i - 1;\n                // 如果右边界越界，就可以退出当前循环\n                if (j >= n) {\n                    break;\n                }\n\n                if (s[i] != s[j]) {\n                    dp[i][j] = false;\n                } else {\n                    if (j - i < 3) {\n                        dp[i][j] = true;\n                    } else {\n                        dp[i][j] = dp[i + 1][j - 1];\n                    }\n                }\n\n                // 只要 dp[i][L] == true 成立，就表示子串 s[i..L] 是回文，此时记录回文长度和起始位置\n                if (dp[i][j] && j - i + 1 > maxLen) {\n                    maxLen = j - i + 1;\n                    begin = i;\n                }\n            }\n        }\n        return s.substr(begin, maxLen);\n    }\n};\n\n// ==================================================\n\nint main() {\n    string line;\n    getline(cin, line);\n    string s = line;\n\n    string result = Solution().longestPalindrome(s);\n    cout << result << endl;\n\n    return 0;\n}\n',11,'Wrong Answer','第 1/1 个测试用例答案错误\n期望输出:\n[0,1]\n\n实际输出:\n,11,\n\n[复杂度分析] 时间复杂度: O(n²), 空间复杂度: O(n)（含递归栈 O(n)）',0.01,3608,'2026-07-31 12:06:48'),(197,5,44,'test','两数之和','cpp','#include <iostream>\n#include <vector>\n#include <unordered_map>\n#include <sstream>\nusing namespace std;\n\nvector<int> twoSum(vector<int>& nums, int target) {\n    unordered_map<int, int> map; // 存储 {数值: 下标}\n    \n    for (int i = 0; i < nums.size(); i++) {\n        int complement = target - nums[i]; // 要找的另一个数\n        \n        // 如果 map 里有这个数，说明找到了\n        if (map.find(complement) != map.end()) {\n            return {map[complement], i};\n        }\n        \n        // 没找到，把当前数存进去\n        map[nums[i]] = i;\n    }\n    \n    return {}; // 理论上不会执行到这里（题目保证有解）\n}\n\nint main() {\n    vector<int> nums;\n    int target;\n    string input;\n    \n    // 读取 nums = [2,7,11,15], target = 9 这种格式\n    // 简单处理：直接读整数，跳过非数字字符\n    cin >> input; // 读 \"nums\"\n    cin >> input; // 读 \"=\"\n    cin >> input; // 读 \"[2,7,11,15],\"\n    \n    // 从字符串中提取数字\n    stringstream ss(input);\n    string temp;\n    while (getline(ss, temp, \',\')) {\n        // 去掉可能存在的 \'[\' 或 \']\'\n        if (temp.find(\'[\') != string::npos) {\n            temp.erase(0, 1);\n        }\n        if (temp.find(\']\') != string::npos) {\n            temp.erase(temp.find(\']\'), 1);\n            nums.push_back(stoi(temp));\n            break;\n        }\n        nums.push_back(stoi(temp));\n    }\n    \n    // 读取 target\n    cin >> input; // 读 \"target\"\n    cin >> input; // 读 \"=\"\n    cin >> target;\n    \n    // 计算结果\n    vector<int> result = twoSum(nums, target);\n    \n    // 输出格式 [0,1]\n    cout << \"[\" << result[0] << \",\" << result[1] << \"]\" << endl;\n    \n    return 0;\n}',139,'Runtime Error','Segmentation fault (core dumped)\nCommand exited with non-zero status 139\n\n[复杂度分析] 时间复杂度: O(n), 空间复杂度: O(n)',0.06,3472,'2026-07-31 12:08:07'),(198,5,44,'test','两数之和','cpp','#include <iostream>\n#include <vector>\n#include <unordered_map>\nusing namespace std;\n\nvector<int> twoSum(vector<int>& nums, int target) {\n    unordered_map<int, int> map;\n    for (int i = 0; i < nums.size(); i++) {\n        int complement = target - nums[i];\n        if (map.find(complement) != map.end()) {\n            return {map[complement], i};\n        }\n        map[nums[i]] = i;\n    }\n    return {};\n}\n\nint main() {\n    int n, target;\n    vector<int> nums;\n    \n    // 读取数组（不知道长度，读到换行或非数字为止）\n    while (cin >> n) {\n        nums.push_back(n);\n        if (cin.peek() == \'\\n\' || cin.peek() == EOF) break;\n    }\n    \n    // 最后一个读入的是 target？不对，这里需要重新设计输入逻辑\n    // 更稳妥的做法：先读一行数组，再读 target\n    return 0;\n}',11,'Wrong Answer','第 1/1 个测试用例答案错误\n期望输出:\n[0,1]\n\n实际输出:\n\n\n[复杂度分析] 时间复杂度: O(n), 空间复杂度: O(n)',0.01,3584,'2026-07-31 12:09:08'),(199,5,44,'test','两数之和','cpp','#include <iostream>\n#include <vector>\n#include <sstream>\nusing namespace std;\n\nvector<int> twoSum(vector<int>& nums, int target) {\n    for (int i = 0; i < nums.size(); i++) {\n        for (int j = i + 1; j < nums.size(); j++) {\n            if (nums[i] + nums[j] == target) {\n                return {i, j};\n            }\n        }\n    }\n    return {};\n}\n\nint main() {\n    vector<int> nums;\n    int target;\n    string input;\n    \n    // 读取 nums = [2,7,11,15], target = 9\n    cin >> input >> input >> input;\n    \n    stringstream ss(input);\n    string temp;\n    while (getline(ss, temp, \',\')) {\n        if (temp.find(\'[\') != string::npos) {\n            temp.erase(0, 1);\n        }\n        if (temp.find(\']\') != string::npos) {\n            temp.erase(temp.find(\']\'), 1);\n            nums.push_back(stoi(temp));\n            break;\n        }\n        nums.push_back(stoi(temp));\n    }\n    \n    cin >> input >> input >> target;\n    \n    vector<int> result = twoSum(nums, target);\n    cout << \"[\" << result[0] << \",\" << result[1] << \"]\" << endl;\n    \n    return 0;\n}',139,'Runtime Error','Segmentation fault (core dumped)\nCommand exited with non-zero status 139\n\n[复杂度分析] 时间复杂度: O(n²), 空间复杂度: O(1)（含递归栈 O(n)）',0.03,3304,'2026-07-31 12:12:03'),(200,5,44,'test','