 = dummy;\n        ListNode* slow = dummy;\n        for (int i = 0; i < n; ++i) {\n            if (!fast) return head;\n            fast = fast->next;\n        }\n        while (fast->next) {\n            fast = fast->next;\n            slow = slow->next;\n        }\n        ListNode* toDelete = slow->next;\n        if (toDelete) {\n            slow->next = toDelete->next;\n            delete toDelete;\n        }\n        ListNode* result = dummy->next;\n        delete dummy;\n        return result;\n    }\n};\n\nstd::vector<int> parseList(const std::string& line) {\n    std::vector<int> nums;\n    std::string token;\n    for (char c : line) {\n        if (std::isdigit(c) || c == \'-\') token.push_back(c);\n        else {\n            if (!token.empty()) { nums.push_back(std::stoi(token)); token.clear(); }\n        }\n    }\n    if (!token.empty()) nums.push_back(std::stoi(token));\n    return nums;\n}\n\nstd::string serialize(ListNode* head) {\n    std::string out = \"[\";\n    ListNode* cur = head;\n    while (cur) {\n        out += std::to_string(cur->val);\n        if (cur->next) out += \",\";\n        cur = cur->next;\n    }\n    out += \"]\";\n    return out;\n}\n\nint main() {\n    std::string line;\n    std::getline(std::cin, line);\n    std::vector<int> nums = parseList(line);\n    int n;\n    std::cin >> n;\n    ListNode* head = nullptr;\n    ListNode* tail = nullptr;\n    for (int v : nums) {\n        ListNode* node = new ListNode(v);\n        if (!head) head = node;\n        else tail->next = node;\n        tail = node;\n    }\n    Solution sol;\n    ListNode* result = sol.removeNthFromEnd(head, n);\n    std::cout << serialize(result) << std::endl;\n    return 0;\n}',11,'Wrong Answer','第 1/6 个测试用例答案错误\n测试输入:\n9 14 23 92 49 78 90 59 94 81 76 71 38 37 6 70 68 2 0 9 99\n12\n\n期望输出:\n9 14 23 92 49 78 90 59 94 76 71 38 37 6 70 68 2 0 9 99\n\n实际输出:\n[9,14,23,92,49,78,90,59,94,76,71,38,37,6,70,68,2,0,9,99]\n\n[复杂度分析] 时间复杂度: O(n), 空间复杂度: O(1)',NULL,NULL,'2026-08-07 11:44:22'),(347,5,62,'test','删除链表的倒数第 N 个结点','cpp','#include <iostream>\n#include <string>\n#include <sstream>\n#include <vector>\n#include <cctype>\n\nstruct ListNode {\n    int val;\n    ListNode *next;\n    ListNode(int x) : val(x), next(nullptr) {}\n};\n\nclass Solution {\npublic:\n    ListNode* removeNthFromEnd(ListNode* head, int n) {\n        ListNode* dummy = new ListNode(0);\n        dummy->next = head;\n        ListNode* fast = dummy;\n        ListNode* slow = dummy;\n        for (int i = 0; i < n; ++i) {\n            if (!fast) return head;\n            fast = fast->next;\n        }\n        while (fast->next) {\n            fast = fast->next;\n            slow = slow->next;\n        }\n        ListNode* toDelete = slow->next;\n        if (toDelete) {\n            slow->next = toDelete->next;\n            delete toDelete;\n        }\n        ListNode* result = dummy->next;\n        delete dummy;\n        return result;\n    }\n};\n\nstd::vector<int> parseList(const std::string& line) {\n    std::vector<int> nums;\n    std::string token;\n    for (char c : line) {\n        if (std::isdigit(c) || c == \'-\') token.push_back(c);\n        else {\n            if (!token.empty()) { nums.push_back(std::stoi(token)); token.clear(); }\n        }\n    }\n    if (!token.empty()) nums.push_back(std::stoi(token));\n    return nums;\n}\n\nvoid printList(ListNode* head) {\n    ListNode* cur = head;\n    bool first = true;\n    while (cur) {\n        if (!first) std::cout << \" \";\n        std::cout << cur->val;\n        first = false;\n        cur = cur->next;\n    }\n    std::cout << std::endl;\n}\n\nint main() {\n    std::string line;\n    std::getline(std::cin, line);\n    std::vector<int> nums = parseList(line);\n    int n;\n    std::cin >> n;\n    ListNode* head = nullptr;\n    ListNode* tail = nullptr;\n    for (int v : nums) {\n        ListNode* node = new ListNode(v);\n        if (!head) head = node;\n        else tail->next = node;\n        tail = node;\n    }\n    Solution sol;\n    ListNode* result = sol.removeNthFromEnd(head, n);\n    printList(result);\n    return 0;\n}',10,'Accepted','通过 6/6 个测试用例\n\n[复杂度分析] 时间复杂度: O(n), 空间复杂度: O(1)',0.01,3856,'2026-08-07 11:44:30'),(348,5,62,'test','删除链表的倒数第 N 个结点','cpp','#include <iostream>\nusing namespace std;\n\nint main() {\n\n    return 0;\n}\n',11,'Wrong Answer','第 1/6 个测试用例答案错误\n测试输入:\n9 14 23 92 49 78 90 59 94 81 76 71 38 37 6 70 68 2 0 9 99\n12\n\n期望输出:\n9 14 23 92 49 78 90 59 94 76 71 38 37 6 70 68 2 0 9 99\n\n实际输出:\n\n\n[复杂度分析] 时间复杂度: O(1), 空间复杂度: O(1)',NULL,NULL,'2026-08-07 12:04:17'),(349,5,62,'test','删除链表的倒数第 N 个结点','cpp','#include <iostream>\nusing namespace std;\n\nint main() {\n\n    while(true);\n    return 0;\n}\n',124,'Time Limit Exceeded','超出时间限制\n\n[复杂度分析] 时间复杂度: O(n), 空间复杂度: O(1)',0,0,'2026-08-07 12:04:38'),(350,5,62,'test','删除链表的倒数第 N 个结点','cpp','#include <iostream>\nusing namespace std;\n\nint main() {\n\n    for(int i=0;i<)\n    return 0;\n}\n',2,'Compile Error','/app/Main.cpp: In function \'int main()\':\n/app/Main.cpp:6:19: error: expected primary-expression before \')\' token\n    6 |     for(int i=0;i<)\n      |                   ^\n/app/Main.cpp:6:19: error: expected \';\' before \')\' token\n    6 |     for(int i=0;i<)\n      |                   ^\n      |                   ;\n',NULL,NULL,'2026-08-07 12:05:43'),(351,5,63,'test','盛最多水的容器','cpp','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int maxArea(vector<int>& height) {\n        int left = 0;\n        int right = height.size() - 1;\n        int maxWater = 0;\n\n        while (left < right) {\n            int width = right - left;\n            int currentHeight = min(height[left], height[right]);\n            int currentWater = width * currentHeight;\n            maxWater = max(maxWater, currentWater);\n\n            if (height[left] < height[right]) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n\n        return maxWater;\n    }\n};\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n;\n    cin >> n;  // 读取数组长度\n\n    vector<int> height(n);\n    for (int i = 0; i < n; i++) {\n        cin >> height[i];  // 读取每个元素\n    }\n\n    Solution solution;\n    cout << solution.maxArea(height) << endl;\n\n    return 0;\n}',10,'Accepted','通过 9/9 个测试用例\n\n[复杂度分析] 时间复杂度: O(n), 空间复杂度: O(1)',0.07,3852,'2026-08-07 12:11:48'),(352,5,63,'test','盛最多水的容器','cpp','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int maxArea(vector<int>& height) {\n        int left = 0;\n        int right = height.size() - 1;\n        int maxWater = 0;\n\n        while (left < right) {\n            int width = right - left;\n            int currentHeight = min(height[left], height[right]);\n            int currentWater = width * currentHeight;\n            maxWater = max(maxWater, currentWater);\n\n            if (height[left] < height[right]) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n\n        return maxWater;\n    }\n};\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n;\n    cin >> n;  // 读取数组长度\n\n    vector<int> height();\n    for (int i = 0; i < n; i++) {\n        cin >> height[i];  // 读取每个元素\n    }\n\n    Solution solution;\n    cout << solution.maxArea(height) << endl;\n\n    return 0;\n}',2,'Compile Error','/app/Main.cpp: In function \'int main()\':\n/app/Main.cpp:37:23: warning: empty parentheses were disambiguated as a function declaration [-Wvexing-parse]\n   37 |     vector<int> height();\n      |                       ^~\n/app/Main.cpp:37:23: note: remove parentheses to default-initialize a variable\n   37 |     vector<int> height();\n      |                       ^~\n      |                       --\n/app/Main.cpp:39:24: warning: pointer to a function used in ari