include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int maxArea(vector<int>& height) {\n        int left = 0;\n        int right = height.size() - 1;\n        int maxWater = 0;\n\n        while (left < right) {\n            int width = right - left;\n            int currentHeight = min(height[left], height[right]);\n            int currentWater = width * currentHeight;\n            maxWater = max(maxWater, currentWater);\n\n            if (height[left] < height[right]) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n\n        return maxWater;\n    }\n};\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n;\n    cin >> n;  // 读取数组长度\n\n    vector<int> height();\n    for (int i = 0; i < n; i++) {\n        cin >> height[i];  // 读取每个元素\n    }\n\n    Solution solution;\n    cout << solution.maxArea(height) << endl;\n\n    return 0;\n}',2,'Compile Error','/app/Main.cpp: In function \'int main()\':\n/app/Main.cpp:37:23: warning: empty parentheses were disambiguated as a function declaration [-Wvexing-parse]\n   37 |     vector<int> height();\n      |                       ^~\n/app/Main.cpp:37:23: note: remove parentheses to default-initialize a variable\n   37 |     vector<int> height();\n      |                       ^~\n      |                       --\n/app/Main.cpp:39:24: warning: pointer to a function used in arithmetic [-Wpointer-arith]\n   39 |         cin >> height[i];  // 读取每个元素\n      |                        ^\n/app/Main.cpp:39:13: error: no match for \'operator>>\' (operand types are \'std::istream\' {aka \'std::basic_istream<char>\'} and \'std::vector<int>()\')\n   39 |         cin >> height[i];  // 读取每个元素\n      |         ~~~ ^~ ~~~~~~~~~\n      |         |              |\n      |         |              std::vector<int>()\n      |         std::istream {aka std::basic_istream<char>}\nIn file included from /usr/include/c++/13/iostream:42,\n            