INSERT INTO `config_info` VALUES (7,'shared-jdbc.yaml','DEFAULT_GROUP','spring:\n    datasource:\n        driver-class-name: com.mysql.cj.jdbc.Driver\n        url: jdbc:mysql://${doj.db.host:127.0.0.1}:3307/${doj.db.name}\n        username: ${doj.db.user:root}\n        password: ${doj.db.pwd:123}\n        hikari:\n            auto-commit: true\n            maximum-pool-size: 10\n            minimum-idle: 10\n            connection-test-query: select 1\n            connection-timeout: 20000\nmybatis-plus:\n    global-config:\n        db-config:\n            update-strategy: not_null\n            id-type: auto','a4bb2606e60b4fc6c90011579337fd43','2026-06-29 23:02:54','2026-06-29 23:36:53',NULL,'172.19.0.1','','','','','','yaml','',''),(8,'shared-swagger.yaml','DEFAULT_GROUP','logging:\r\n    level:\r\n        com.decade: debug\r\n    pattern:\r\n        dateformat: HH:mm:ss:SSS\r\nknife4j:\r\n    enable: true\r\n    openapi:\r\n        title: ${doj.swagger.title}\r\n        description: \"Duck Online Judge API\"\r\n        email: \"decade-qzj@foxmail.com\"\r\n        version: v1.0.0\r\n        group:\r\n            default:\r\n                group-name: default\r\n                api-rule: package\r\n                api-rule-resources:\r\n                    - ${doj.swagger.scan}','6a283d642acd6da26f559796f0046222','2026-06-29 23:04:52','2026-06-29 23:04:52',NULL,'172.19.0.1','','',NULL,NULL,NULL,'yaml',NULL,''),(9,'shared-jwt.yaml','DEFAULT_GROUP','doj:\r\n    jwt:\r\n        location: classpath:doj.jks\r\n        alias: decade\r\n        password: doj123\r\n        tokenTTL: 30m\r\n        refreshTokenTTL: 7d\r\n        authorization: \"authorization\"\r\n        secret-key: \"uid\"','d8f5a62c514c889dc496ce10c6406751','2026-06-29 23:05:21','2026-06-29 23:05:21',NULL,'172.19.0.1','','',NULL,NULL,NULL,'yaml',NULL,''),(10,'shared-rabbitmq.yaml','DEFAULT_GROUP','spring:\r\n    rabbitmq:\r\n        host: ${doj.mq.host:127.0.0.1}\r\n        port: 5672\r\n        username: guest\r\n        password: guest','c36fdc96fba8a74b5a6d2223b69fd605','2026-06-29 23:05:45','2026-06-29 23:05:45',NULL,'172.19.0.1','','',NULL,NULL,NULL,'yaml',NULL,''),(11,'gateway-sentinel-rules','DEFAULT_GROUP','[\r\n    {\r\n        \"resource\": \"/user/**\",\r\n        \"count\": 10,\r\n        \"intervalSec\": 1,\r\n        \"grade\": 1\r\n    }\r\n]','d10d2b607e6a883a9d9daaa700732c1c','2026-06-29 23:11:45','2026-06-29 23:11:45',NULL,'172.19.0.1','','',NULL,NULL,NULL,'json',NULL,''),(12,'gateway-sentinel-degrade-rules','DEFAULT_GROUP','[\r\n    {\r\n        \"resource\": \"/problem/**\",\r\n        \"grade\": 0,\r\n        \"count\": 0.5,\r\n        \"timeWindow\": 10\r\n    }\r\n]','bd53cdc7115aba903d503982a1be304c','2026-06-29 23:17:51','2026-06-29 23:17:51',NULL,'172.19.0.1','','',NULL,NULL,NULL,'yaml',NULL,'');
